#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>

#define MAX_TEXT_LEN 1024

static void usage(void) {
    puts("USAGE");
}

static int parse_shift(const char *s, int *out_shift) {
    char *endptr = NULL;
    long val;
    if (s == NULL || *s == '\0')
        return -1;
    errno = 0;
    val = strtol(s, &endptr, 10);
    if (errno != 0 || endptr == s || *endptr != '\0')
        return -1;
    int shift = (int)val % 26;
    if (shift < 0) shift += 26;
    *out_shift = shift;
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        usage();
        return 0;
    }
    int shift;
    if (parse_shift(argv[1], &shift) != 0) {
        usage();
        return 0;
    }
    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > MAX_TEXT_LEN) {
        usage();
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (isupper(c)) {
            c = (unsigned char)('A' + (c - 'A' + shift) % 26);
        } else if (islower(c)) {
            c = (unsigned char)('a' + (c - 'a' + shift) % 26);
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
